# Use aarch64 objdump if available, otherwise try readelf with wider output
readelf -W --dyn-syms /tmp/libmonosgen-2.0.so 2>/dev/null | awk '$4 == "FUNC" && $7 != "UND" {print $2, $3, $8}' | sort > /tmp/mono_syms_wide.txt
head -5 /tmp/mono_syms_wide.txt
