grep "0x222" /tmp/mono_syms_wide.txt || true
# Look for symbols near our addresses
python3 -c "
syms = []
with open('/tmp/mono_syms_wide.txt') as f:
    for l in f:
        p = l.strip().split(None, 2)
        if len(p) >= 3:
            syms.append((int(p[0],16), int(p[1]), p[2]))
syms.sort()

targets = [0x222098, 0x2241ac, 0x1abc80, 0x16de04, 0x2f4b20, 0x2f4c84, 0x2c1a40]
for t in targets:
    # Find nearest symbol before
    best = None
    for a, s, n in syms:
        if a <= t:
            best = (a, s, n)
        else:
            break
    if best:
        print(f'0x{t:x}: {best[2]} @ 0x{best[0]:x} size={best[1]} offset=+0x{t-best[0]:x}')
    else:
        print(f'0x{t:x}: ??')
