# Fix: some sizes might be in hex with 0x prefix
python3 << 'PYEOF'
syms = []
with open('/tmp/mono_full_syms.txt') as f:
    for l in f:
        p = l.strip().split(None, 2)
        if len(p) >= 3:
            a = int(p[0], 16)
            try:
                s = int(p[1])
            except ValueError:
                s = int(p[1], 16) if p[1].startswith('0x') else 0
            if a > 0:
                syms.append((a, s, p[2]))
syms.sort()

def lookup(pc):
    lo, hi = 0, len(syms) - 1
    best = None
    while lo <= hi:
        mid = (lo + hi) // 2
        if syms[mid][0] <= pc:
            best = mid
            lo = mid + 1
        else:
            hi = mid - 1
    if best is not None:
        a, s, n = syms[best]
        offset = pc - a
        if s > 0 and offset < s:
            return n, offset
        if best + 1 < len(syms) and pc < syms[best+1][0]:
            return n, offset
        return n + " (nearest)", offset
    return "??", 0

entries = [
    ("Thread 7020 (main/crash) - tid: 7020", [
        ("#01", 0x222098),
        ("#02", 0x2241ac),
        ("#03", 0x1abc80),
        ("#04", 0x16de04),
    ]),
    ("Thread 7046 (SGen worker) - tid: 7046", [
        ("#02", 0x2f4b20),
        ("#03", 0x2f4c84),
    ]),
    ("Thread 7048 (Finalizer) - tid: 7048", [
        ("#02", 0x2c1a40),
    ]),
]

for thread, frames in entries:
    print(f"\n{thread}:")
    for fid, pc in frames:
        name, off = lookup(pc)
        print(f"  {fid} pc 0x{pc:08x}  {name}+0x{off:x}")
