# Fix parsing - readelf output columns may vary
readelf -W -s /tmp/libmonosgen-2.0.so.dbg 2>/dev/null | grep ' FUNC ' | head -3

# Get all FUNC symbols properly
readelf -W -s /tmp/libmonosgen-2.0.so.dbg 2>/dev/null | awk '/FUNC/ && $2 != "0000000000000000" {
    for(i=1;i<=NF;i++) {
        if($i == "FUNC") { print $2, $(NF); break }
    }
}' | sort -u > /tmp/mono_func_syms.txt
wc -l /tmp/mono_func_syms.txt

python3 << 'PYEOF'
syms = []
with open('/tmp/mono_func_syms.txt') as f:
    for l in f:
        p = l.strip().split(None, 1)
        if len(p) == 2:
            try:
                a = int(p[0], 16)
                if a > 0:
                    syms.append((a, p[1]))
            except ValueError:
                pass
syms.sort()

for t in [0x2f4b20, 0x2f4c84]:
    prev = None
    for a, n in syms:
        if a > t:
            if prev:
                print(f'{hex(t)}: {prev[1]}@{hex(prev[0])} (+{hex(t-prev[0])}), next: {n}@{hex(a)}')
            break
        prev = (a, n)
