{"command": "# Check the max address of symbols
python3 << 'PYEOF'
import subprocess, re

result = subprocess.run(
    ['readelf', '-W', '-s', '/tmp/libmonosgen-2.0.so.dbg'],
    capture_output=True, text=True
)

max_addr = 0
count = 0
for line in result.stdout.split('\n'):
    m = re.match(r'\s+\d+:\s+([0-9a-f]+)\s+(\d+)\s+FUNC\s', line)
    if m:
        addr = int(m.group(1), 16)
        if addr > 0:
            count += 1
            if addr > max_addr:
                max_addr = addr

print(f"Count: {count}, Max addr: {hex(max_addr)}")

# Our targets are at 0x2f4b20 and 0x2f4c84, so let's see what's around there
# Check all symbols (any type) near 0x2f0000-0x300000
near = []
for line in result.stdout.split('\n'):
    m = re.match(r'\s+\d+:\s+([0-9a-f]+)\s+(\d+)\s+(\S+)\s+(\S+)\s+(\S+)\s+(\S+)\s+(.*)', line)
    if m:
        addr = int(m.group(1), 16)
        if 0x2f0000 <= addr <= 0x300000:
            near.append((addr, m.group(3), m.group(7).strip()))

near.sort()
for a, t, n in near:
    print(f"  {hex(a)} {t} {n}")
PYEOF", "description": "Check symbol address ranges"}
